//! Read-only construction studies generated by the same compiler as the bench.
use super::{design::Design, form::{self, Ask, Style}};
use std::sync::OnceLock;

pub fn preview(era: &str) -> Option<&'static [u8]> {
    static WATER: OnceLock<Vec<u8>> = OnceLock::new();
    static STEAM: OnceLock<Vec<u8>> = OnceLock::new();
    static ELECTRIC: OnceLock<Vec<u8>> = OnceLock::new();
    let (cache, source) = match era {
        "water" => (&WATER, include_str!("../../designs/19-waterline.machine")),
        "steam" => (&STEAM, include_str!("../../designs/20-steamline.machine")),
        "electric" => (&ELECTRIC, include_str!("../../designs/21-electricline.machine")),
        _ => return None,
    };
    Some(cache.get_or_init(|| {
        let design = Design::parse(source).expect("shipped era study");
        let scene = form::build(&design, Ask { style: Style::Yard, ..Ask::default() })
            .expect("shipped era study form");
        let eye = form::shot::Eye {
            yaw: if era == "water" { -2.25 } else { 0.72 },
            pitch: 0.34,
            zoom: 0.65,
        };
        form::shot::render_export(&scene, 720, 480, eye, 0, true).png()
    }).as_slice())
}
